private static bool GithubBlobMatches(string FilePath, string ExpectedObjectId) {
    if (ExpectedObjectId.IsNullEmptyWhitespace() || ExpectedObjectId.Length != 40 ||
        !ExpectedObjectId.All(Uri.IsHexDigit) || !File.Exists(FilePath)) return false;
    try {
        long Length = new FileInfo(FilePath).Length;
        byte[] Header = Encoding.ASCII.GetBytes($"blob {Length}\0");
        using SHA1 Hasher = SHA1.Create();
        using CryptoStream HashStream = new(Stream.Null, Hasher, CryptoStreamMode.Write);
        HashStream.Write(Header, 0, Header.Length);
        using (FileStream Input = File.OpenRead(FilePath)) Input.CopyTo(HashStream);
        HashStream.FlushFinalBlock();
        string Actual = BitConverter.ToString(Hasher.Hash!).Replace("-", string.Empty).ToLowerInvariant();
        return Actual.Equals(ExpectedObjectId, StringComparison.OrdinalIgnoreCase);
    }
    catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or CryptographicException) {
        return false;
    }
}

